16	const scoreSphinx = (otherCards: Card[]): number => {
17	  const typeCount = countMonsterTypes(otherCards);
18	  if (typeCount <= MAX_TYPES_FOR_BASE_SCORE) return BASE_SCORE;
19	
20	  const extraTypes = typeCount - MAX_TYPES_FOR_BASE_SCORE;
21	  return SCORE_AT_FIRST_EXTRA_TYPE + SCORE_PER_EXTRA_TYPE * (extraTypes - 1);
